   168	static int32_t ui_demo_wifi_signal_from_rssi(int32_t rssi)
   169	{
   170	  if (rssi == 0)
   171	    {
   172	      return 0;
   173	    }
   174	
   175	  if (rssi >= -35)
   176	    {
   177	      return 100;
   178	    }
   179	
   180	  if (rssi <= -95)
   181	    {
   182	      return 5;
   183	    }
   184	
   185	  return 5 + ((rssi + 95) * 95) / 60;
   186	}
