   188	static void ui_demo_wifi_store_or_update_ap(struct ui_demo_wifi_ap *aps,
   189	                                            size_t *count,
   190	                                            const struct ui_demo_wifi_ap *ap)
   191	{
   192	  size_t i;
   193	
   194	  for (i = 0; i < *count; i++)
   195	    {
   196	      if (strcmp(aps[i].ssid, ap->ssid) == 0)
   197	        {
   198	          if (ap->rssi > aps[i].rssi)
   199	            {
   200	              aps[i] = *ap;
   201	            }
   202	
   203	          return;
   204	        }
   205	    }
   206	
   207	  if (*count < UI_DEMO_WIFI_MAX_APS)
   208	    {
   209	      aps[*count] = *ap;
   210	      (*count)++;
   211	    }
   212	}
