   214	static uint32_t ui_demo_wifi_channel_from_freq(uint32_t freq)
   215	{
   216	  if (freq >= 2412 && freq <= 2472)
   217	    {
   218	      return (freq - 2407) / 5;
   219	    }
   220	
   221	  if (freq == 2484)
   222	    {
   223	      return 14;
   224	    }
   225	
   226	  if (freq >= 5000 && freq <= 5900)
   227	    {
   228	      return (freq - 5000) / 5;
   229	    }
   230	
   231	  return freq;
   232	}
