   234	static size_t ui_demo_wifi_read_scan_results(struct ui_demo_wifi_ap *aps,
   235	                                             size_t max_count)
   236	{
   237	  size_t count = 0;
   238	  int idx;
   239	
   240	  if (aps == NULL || max_count == 0)
   241	    {
   242	      return 0;
   243	    }
   244	
   245	  for (idx = 0; idx < UI_DEMO_WIFI_DRIVER_MAX_APS; idx++)
   246	    {
   247	      struct ui_demo_wifi_driver_scan_result result;
   248	      struct ui_demo_wifi_ap ap;
   249	      size_t ssid_len;
   250	      int ret;
   251	
   252	      memset(&result, 0, sizeof(result));
   253	      ret = fhost_get_scan_results(NULL, idx, 1, &result);
   254	      if (ret <= 0)
   255	        {
   256	          break;
   257	        }
   258	
   259	      if (!result.valid_flag || result.ssid.length == 0)
   260	        {
   261	          continue;
   262	        }
   263	
   264	      memset(&ap, 0, sizeof(ap));
   265	      ssid_len = result.ssid.length;
   266	      if (ssid_len > UI_DEMO_WIFI_DRIVER_SSID_LEN)
   267	        {
   268	          ssid_len = UI_DEMO_WIFI_DRIVER_SSID_LEN;
   269	        }
   270	
   271	      if (ssid_len >= sizeof(ap.ssid))
   272	        {
   273	          ssid_len = sizeof(ap.ssid) - 1;
   274	        }
   275	
   276	      memcpy(ap.ssid, result.ssid.array, ssid_len);
   277	      ap.ssid[ssid_len] = '\0';
   278	      ap.rssi = (int32_t)result.rssi;
   279	      ap.signal = ui_demo_wifi_signal_from_rssi(ap.rssi);
   280	      ap.channel = result.chan == NULL ? 0 :
   281	                   ui_demo_wifi_channel_from_freq(result.chan->freq);
   282	      snprintf(ap.status, sizeof(ap.status),
   283	               "CH %lu  RSSI %ld dBm",
   284	               (unsigned long)ap.channel, (long)ap.rssi);
   285	
   286	      ui_demo_wifi_store_or_update_ap(aps, &count, &ap);
   287	      if (count >= max_count)
   288	        {
   289	          break;
   290	        }
   291	    }
   292	
   293	  return count;
   294	}
