   297	static bool ui_demo_wifi_password_is_hex64(const char *password)
   298	{
   299	  size_t i;
   300	
   301	  if (password == NULL || strlen(password) != 64)
   302	    {
   303	      return false;
   304	    }
   305	
   306	  for (i = 0; i < 64; i++)
   307	    {
   308	      char ch = password[i];
   309	
   310	      if (!((ch >= '0' && ch <= '9') ||
   311	            (ch >= 'a' && ch <= 'f') ||
   312	            (ch >= 'A' && ch <= 'F')))
   313	        {
   314	          return false;
   315	        }
   316	    }
   317	
   318	  return true;
   319	}
