   159	static bool ui_demo_bluetooth_is_pid_dir(const char *name)
   160	{
   161	  if (name == NULL || name[0] == '\0')
   162	    {
   163	      return false;
   164	    }
   165	
   166	  for (; *name != '\0'; name++)
   167	    {
   168	      if (*name < '0' || *name > '9')
   169	        {
   170	          return false;
   171	        }
   172	    }
   173	
   174	  return true;
   175	}
