   177	static bool ui_demo_bluetooth_cmdline_matches(const char *cmdline,
   178	                                              const char *name)
   179	{
   180	  const char *base;
   181	  const char *end;
   182	  size_t name_len;
   183	  size_t base_len;
   184	
   185	  if (cmdline == NULL || name == NULL)
   186	    {
   187	      return false;
   188	    }
   189	
   190	  while (*cmdline == ' ' || *cmdline == '\t')
   191	    {
   192	      cmdline++;
   193	    }
   194	
   195	  base = strrchr(cmdline, '/');
   196	  base = base == NULL ? cmdline : base + 1;
   197	  end = base;
   198	  while (*end != '\0' && *end != ' ' && *end != '\t' &&
   199	         *end != '\r' && *end != '\n')
   200	    {
   201	      end++;
   202	    }
   203	
   204	  name_len = strlen(name);
   205	  base_len = (size_t)(end - base);
   206	  return base_len == name_len && strncmp(base, name, name_len) == 0;
   207	}
