   209	static int ui_demo_bluetooth_read_cmdline(pid_t pid, char *buf, size_t len)
   210	{
   211	#ifdef CONFIG_FS_PROCFS
   212	  char path[32];
   213	  ssize_t nread;
   214	  int fd;
   215	  size_t i;
   216	
   217	  if (buf == NULL || len == 0)
   218	    {
   219	      return -EINVAL;
   220	    }
   221	
   222	  snprintf(path, sizeof(path), UI_DEMO_BLUETOOTH_PROC_ROOT "/%d/cmdline",
   223	           (int)pid);
   224	  fd = open(path, O_RDONLY);
   225	  if (fd < 0)
   226	    {
   227	      return -errno;
   228	    }
   229	
   230	  nread = read(fd, buf, len - 1);
   231	  close(fd);
   232	  if (nread <= 0)
   233	    {
   234	      return nread == 0 ? -ENOENT : -errno;
   235	    }
   236	
   237	  for (i = 0; i < (size_t)nread; i++)
   238	    {
   239	      if (buf[i] == '\0')
   240	        {
   241	          buf[i] = ' ';
   242	        }
   243	    }
   244	
   245	  buf[nread] = '\0';
   246	  return 0;
   247	#else
   248	  (void)pid;
   249	  (void)buf;
   250	  (void)len;
   251	  return -ENOSYS;
   252	#endif
   253	}
