   255	static int ui_demo_bluetooth_count_processes(const char *name,
   256	                                             pid_t *first_pid)
   257	{
   258	#ifdef CONFIG_FS_PROCFS
   259	  DIR *dir;
   260	  struct dirent *entry;
   261	  int count = 0;
   262	
   263	  if (first_pid != NULL)
   264	    {
   265	      *first_pid = -1;
   266	    }
   267	
   268	  if (name == NULL)
   269	    {
   270	      return -EINVAL;
   271	    }
   272	
   273	  dir = opendir(UI_DEMO_BLUETOOTH_PROC_ROOT);
   274	  if (dir == NULL)
   275	    {
   276	      return -errno;
   277	    }
   278	
   279	  while ((entry = readdir(dir)) != NULL)
   280	    {
   281	      char cmdline[80];
   282	      pid_t pid;
   283	
   284	      if (!ui_demo_bluetooth_is_pid_dir(entry->d_name))
   285	        {
   286	          continue;
   287	        }
   288	
   289	      pid = (pid_t)atoi(entry->d_name);
   290	      if (pid <= 0 ||
   291	          ui_demo_bluetooth_read_cmdline(pid, cmdline,
   292	                                         sizeof(cmdline)) < 0)
   293	        {
   294	          continue;
   295	        }
   296	
   297	      if (ui_demo_bluetooth_cmdline_matches(cmdline, name))
   298	        {
   299	          if (count == 0 && first_pid != NULL)
   300	            {
   301	              *first_pid = pid;
   302	            }
   303	
   304	          count++;
   305	        }
   306	    }
   307	
   308	  closedir(dir);
   309	  return count;
   310	#else
   311	  if (first_pid != NULL)
   312	    {
   313	      *first_pid = -1;
   314	    }
   315	
   316	  (void)name;
   317	  return -ENOSYS;
   318	#endif
   319	}
