   332	static bool ui_demo_bluetooth_apply_output_locked(const char *line,
   333	                                                  bool stop_output)
   334	{
   335	  const bool is_error = ui_demo_bluetooth_line_is_error(line);
   336	
   337	  if (stop_output)
   338	    {
   339	      return false;
   340	    }
   341	
   342	  if (!is_error && g_bluetooth.status == UI_DEMO_BLUETOOTH_STATUS_ERROR)
   343	    {
   344	      return false;
   345	    }
   346	
   347	  if (is_error)
   348	    {
   349	      g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_ERROR;
   350	      g_bluetooth.start_in_progress = false;
   351	      g_bluetooth.last_error = -EIO;
   352	      ui_demo_bluetooth_set_message_locked("失败：%s", line);
   353	      return true;
   354	    }
   355	
   356	  if (ui_demo_bluetooth_line_has(line, "gatts connected") ||
   357	      ui_demo_bluetooth_line_has(line, "gattserver connected"))
   358	    {
   359	      g_bluetooth.connected = true;
   360	      g_bluetooth.server_running = true;
   361	      g_bluetooth.start_in_progress = false;
   362	      g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_CONNECTED;
   363	      ui_demo_bluetooth_set_message_locked("成功：手机已连接");
   364	      return true;
   365	    }
   366	
   367	  if (ui_demo_bluetooth_line_has(line, "gatts disconnected") ||
   368	      ui_demo_bluetooth_line_has(line, "peer disconnected"))
   369	    {
   370	      g_bluetooth.connected = false;
   371	      g_bluetooth.server_running = true;
   372	      g_bluetooth.start_in_progress = false;
   373	      g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_ADVERTISING;
   374	      ui_demo_bluetooth_set_message_locked(
   375	        "成功：连接已断开，继续等待手机连接");
   376	      return true;
   377	    }
   378	
   379	  if (ui_demo_bluetooth_line_has(line, "advertising handle") ||
   380	      ui_demo_bluetooth_line_has(line, "connect now") ||
   381	      ui_demo_bluetooth_line_has(line, "advertising started") ||
   382	      ui_demo_bluetooth_line_has(line,
   383	        "LE_SET_EXT_ADV_ENABLE status=0x00"))
   384	    {
   385	      g_bluetooth.connected = false;
   386	      g_bluetooth.server_running = true;
   387	      g_bluetooth.start_in_progress = false;
   388	      g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_ADVERTISING;
   389	      ui_demo_bluetooth_set_message_locked(
   390	        "成功：蓝牙已开启，等待手机连接");
   391	      return true;
   392	    }
   393	
   394	  if (ui_demo_bluetooth_line_has(line, "start persistent GATT server"))
   395	    {
   396	      g_bluetooth.connected = false;
   397	      g_bluetooth.server_running = true;
   398	      g_bluetooth.status = UI_DEMO_BLUETOOTH_STATUS_STARTING;
   399	      ui_demo_bluetooth_set_message_locked(
   400	        "正在设置 %s 并开启广播...",
   401	        g_bluetooth.device_name);
   402	      return true;
   403	    }
   404	
   405	  return false;
   406	}
