   432	static int ui_demo_bluetooth_wait_pid(pid_t pid, unsigned int wait_ms,
   433	                                      int *exit_code)
   434	{
   435	#ifdef CONFIG_SCHED_WAITPID
   436	  unsigned int waited = 0;
   437	  int status = 0;
   438	  int ret;
   439	
   440	  while (waited <= wait_ms)
   441	    {
   442	      ret = waitpid(pid, &status, WNOHANG);
   443	      if (ret == pid)
   444	        {
   445	          int code = 0;
   446	
   447	#ifdef WIFEXITED
   448	          if (WIFEXITED(status))
   449	            {
   450	              code = WEXITSTATUS(status);
   451	            }
   452	          else
   453	            {
   454	              code = status == 0 ? 0 : 1;
   455	            }
   456	#else
   457	          code = status == 0 ? 0 : 1;
   458	#endif
   459	
   460	          if (exit_code != NULL)
   461	            {
   462	              *exit_code = code;
   463	            }
   464	
   465	          return 0;
   466	        }
   467	
   468	      if (ret < 0)
   469	        {
   470	          if (errno == ECHILD || errno == ESRCH)
   471	            {
   472	              if (exit_code != NULL)
   473	                {
   474	                  *exit_code = 0;
   475	                }
   476	
   477	              return 0;
   478	            }
   479	
   480	          return -errno;
   481	        }
   482	
   483	      usleep(UI_DEMO_BLUETOOTH_WAIT_SLICE_MS * 1000);
   484	      waited += UI_DEMO_BLUETOOTH_WAIT_SLICE_MS;
   485	    }
   486	
   487	  return -ETIMEDOUT;
   488	#else
   489	  (void)pid;
   490	  usleep(wait_ms * 1000);
   491	  if (exit_code != NULL)
   492	    {
   493	      *exit_code = 0;
   494	    }
   495	
   496	  return 0;
   497	#endif
   498	}
