   515	  memset(&param, 0, sizeof(param));
   516	  param.sched_priority = priority;
   517	  ret = posix_spawnattr_setschedparam(attr, &param);
   518	  if (ret != 0)
   519	    {
   520	      posix_spawnattr_destroy(attr);
   521	      return -ret;
   522	    }
   523	
   524	  ret = posix_spawnattr_setstacksize(attr, stacksize);
   525	  if (ret != 0)
   526	    {
   527	      posix_spawnattr_destroy(attr);
   528	      return -ret;
   529	    }
   530	
   531	#if defined(CONFIG_RR_INTERVAL) && CONFIG_RR_INTERVAL > 0
   532	  ret = posix_spawnattr_setschedpolicy(attr, SCHED_RR);
   533	  if (ret != 0)
   534	    {
   535	      posix_spawnattr_destroy(attr);
   536	      return -ret;
   537	    }
   538	
   539	  ret = posix_spawnattr_setflags(attr,
   540	                                 POSIX_SPAWN_SETSCHEDPARAM |
   541	                                 POSIX_SPAWN_SETSCHEDULER);
   542	#else
   543	  ret = posix_spawnattr_setflags(attr, POSIX_SPAWN_SETSCHEDPARAM);
   544	#endif
   545	  if (ret != 0)
   546	    {
   547	      posix_spawnattr_destroy(attr);
   548	      return -ret;
   549	    }
