   633	    {
   634	      ret = posix_spawn_file_actions_adddup2(&file_actions, pipefd[1],
   635	                                             STDERR_FILENO);
   636	    }
   637	
   638	  if (ret == 0)
   639	    {
   640	      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[0]);
   641	    }
   642	
   643	  if (ret == 0)
   644	    {
   645	      ret = posix_spawn_file_actions_addclose(&file_actions, pipefd[1]);
   646	    }
   647	
   648	  if (ret != 0)
   649	    {
   650	      posix_spawn_file_actions_destroy(&file_actions);
