   661	    {
   662	      posix_spawn_file_actions_destroy(&file_actions);
   663	      close(pipefd[0]);
   664	      close(pipefd[1]);
   665	      return ret;
   666	    }
   667	
   668	  pid = task_spawn(name, entry, &file_actions, &attr, argv, NULL);
   669	  posix_spawnattr_destroy(&attr);
   670	  posix_spawn_file_actions_destroy(&file_actions);
   671	  close(pipefd[1]);
   672	  if (pid < 0)
   673	    {
   674	      close(pipefd[0]);
   675	      return pid;
   676	    }
