   683	static int ui_demo_bluetooth_read_capture(
   684	  int read_fd,
   685	  pid_t pid,
   686	  void (*line_cb)(const char *line, void *user_data),
   687	  void *user_data)
   688	{
   689	  struct pollfd pfd;
   690	  char chunk[UI_DEMO_BLUETOOTH_CAPTURE_CHUNK];
   691	  char line[UI_DEMO_BLUETOOTH_CAPTURE_LINE];
   692	  size_t line_len = 0;
   693	  int ret = 0;
   694	  int exit_code = 0;
   695	
   696	  pfd.fd = read_fd;
   697	  pfd.events = POLLIN | POLLHUP;
   698	  pfd.revents = 0;
   699	
   700	  for (;;)
   701	    {
   702	      ssize_t nread;
   703	      size_t i;
   704	
   705	      ret = poll(&pfd, 1, -1);
   706	      if (ret < 0)
   707	        {
   708	          if (errno == EINTR)
   709	            {
   710	              continue;
   711	            }
   712	
   713	          ret = -errno;
   714	          break;
   715	        }
   716	
   717	      if ((pfd.revents & POLLIN) == 0 &&
   718	          (pfd.revents & POLLHUP) != 0)
   719	        {
   720	          ret = 0;
   721	          break;
   722	        }
   723	
   724	      nread = read(read_fd, chunk, sizeof(chunk));
   725	      if (nread < 0)
   726	        {
   727	          if (errno == EINTR || errno == EAGAIN)
   728	            {
   729	              continue;
   730	            }
   731	
   732	          ret = -errno;
   733	          break;
   734	        }
   735	
   736	      if (nread == 0)
   737	        {
   738	          ret = 0;
   739	          break;
