   836	      }
   837	      prompt = after_wake;
   838	    } else {
   839	      prompt = text;
   840	    }
   841	  } else {
   842	    return;
   843	  }
   844	
   845	  if (strcmp(prompt, "讲") == 0 ||
   846	      strcmp(prompt, "讲。") == 0 ||
   847	      strcmp(prompt, "讲一下") == 0 ||
   848	      strcmp(prompt, "讲一下。") == 0) {
