   888	static int submit_utterance(unsigned char *pcm, size_t pcm_len)
   889	{
   890	  int ret = 0;
   891	
   892	  if (pcm == NULL || pcm_len == 0) {
   893	    free(pcm);
   894	    return -EINVAL;
   895	  }
   896	
   897	  pthread_mutex_lock(&s_voice.work_lock);
   898	  if (s_voice.worker_stop ||
   899	      s_voice.work_count >= VOICE_UTTERANCE_QUEUE_DEPTH) {
   900	    ret = -EBUSY;
   901	  } else {
   902	    s_voice.work_queue[s_voice.work_tail].pcm = pcm;
   903	    s_voice.work_queue[s_voice.work_tail].len = pcm_len;
   904	    s_voice.work_tail =
   905	      (s_voice.work_tail + 1) % VOICE_UTTERANCE_QUEUE_DEPTH;
   906	    s_voice.work_count++;
   907	    voice_set_recognizing(true);
   908	    pthread_cond_signal(&s_voice.work_cond);
   909	  }
   910	  pthread_mutex_unlock(&s_voice.work_lock);
   911	
   912	  if (ret < 0) {
   913	    syslog(LOG_WARNING, "[%s] ASR queue full/stopped, dropping %zu bytes\n",
   914	           TAG, pcm_len);
   915	    free(pcm);
   916	  }
   917	  return ret;
   918	}
