   920	static void *voice_asr_worker(void *arg)
   921	{
   922	  (void)arg;
   923	
   924	  while (1) {
   925	    voice_utterance_t item;
   926	
   927	    memset(&item, 0, sizeof(item));
   928	    pthread_mutex_lock(&s_voice.work_lock);
   929	    while (s_voice.work_count == 0 && !s_voice.worker_stop) {
   930	      pthread_cond_wait(&s_voice.work_cond, &s_voice.work_lock);
   931	    }
   932	
   933	    if (s_voice.worker_stop) {
   934	      while (s_voice.work_count > 0) {
   935	        item = s_voice.work_queue[s_voice.work_head];
   936	        memset(&s_voice.work_queue[s_voice.work_head], 0,
   937	               sizeof(s_voice.work_queue[s_voice.work_head]));
   938	        s_voice.work_head =
   939	          (s_voice.work_head + 1) % VOICE_UTTERANCE_QUEUE_DEPTH;
   940	        s_voice.work_count--;
   941	        free(item.pcm);
   942	      }
   943	      pthread_mutex_unlock(&s_voice.work_lock);
   944	      voice_set_recognizing(false);
   945	      break;
   946	    }
   947	
   948	    item = s_voice.work_queue[s_voice.work_head];
   949	    memset(&s_voice.work_queue[s_voice.work_head], 0,
   950	           sizeof(s_voice.work_queue[s_voice.work_head]));
   951	    s_voice.work_head =
   952	      (s_voice.work_head + 1) % VOICE_UTTERANCE_QUEUE_DEPTH;
   953	    s_voice.work_count--;
   954	    pthread_mutex_unlock(&s_voice.work_lock);
   955	
   956	    process_utterance(item.pcm, item.len);
   957	  }
   958	
   959	  return NULL;
   960	}
