   962	static bool voice_should_discard_audio(uint64_t now)
   963	{
   964	  bool discard;
   965	
   966	  pthread_mutex_lock(&s_voice.lock);
   967	  if (s_voice.awaiting_reply &&
   968	      now - s_voice.reply_started_ms > VOICE_REPLY_TIMEOUT_MS) {
   969	    s_voice.awaiting_reply = false;
   970	    s_voice.generation++;
   971	    s_voice.last_activity_ms = now;
   972	    syslog(LOG_WARNING,
   973	           "[%s] reply timeout, resume listening (generation=%u)\n",
   974	           TAG, s_voice.generation);
   975	  }
   976	  discard = s_voice.speaking || s_voice.awaiting_reply ||
   977	            s_voice.recognizing ||
   978	            now < s_voice.suppress_until_ms;
   979	  pthread_mutex_unlock(&s_voice.lock);
   980	  return discard;
   981	}
