   359	  };
   360	
   361	  syslog(LOG_INFO, "[%s] request %zu bytes pcm via %s/%s\n",
   362	         TAG, pcm_len, s_host, s_model);
   363	  status = vela_https_request(s_host, s_port, "POST", s_path,
   364	                              hdrs, body, body_len,
   365	                              resp, VELACLAW_VOICE_RESP_BUF_SIZE,
   366	                              &resp_len);
   367	  free(body);
   368	
   369	  if (status != 200) {
   370	    syslog(LOG_ERR, "[%s] HTTP %d: %.160s\n", TAG, status, resp);
   371	    free(resp);
   372	    return -EIO;
   373	  }
   374	
   375	  ret = parse_asr_response(resp, text_out, text_cap);
   376	  free(resp);
   377	  if (ret != 0) {
   378	    syslog(LOG_WARNING, "[%s] parse failed: %d\n", TAG, ret);
   379	    return ret;
   380	  }
   381	
   382	  syslog(LOG_INFO, "[%s] recognized: %.80s\n", TAG, text_out);
   383	  return 0;
   384	}
