    17	/*
    18	 * audio_capture.c - DMIC capture through the ArtInChip HAL.
    19	 *
    20	 * The board has a working DMIC HAL/DMA path, while the generic media recorder
    21	 * path depends on CONFIG_MEDIA and does not provide pcm0c on this target.
    22	 * Capture is therefore exposed as a small blocking reader over a two-period
    23	 * cyclic DMA buffer.
    24	 */
    25	
    26	#include "voice/audio_capture.h"
    27	#include "velaclaw_config.h"
    28	
    29	#include <errno.h>
    30	#include <limits.h>
    31	#include <nuttx/arch.h>
    32	#include <nuttx/cache.h>
    33	#include <nuttx/irq.h>
    34	#include <stdio.h>
    35	#include <stdlib.h>
    36	#include <string.h>
    37	#include <syslog.h>
    38	#include <unistd.h>
    39	
    40	#include <aic_core.h>
    41	#include <aic_drv_dma.h>
    42	#include <drv_dma.h>
    43	#include <hal_audio.h>
    44	
    45	static const char *TAG = "audio_cap";
    46	
    47	#ifndef CONFIG_AIC_DMIC_CMD_DMA_CHANNEL
    48	#define CONFIG_AIC_DMIC_CMD_DMA_CHANNEL 1
    49	#endif
    50	
    51	#ifndef CACHE_LINE_SIZE
    52	#define CACHE_LINE_SIZE 32
    53	#endif
    54	
    55	#define CAP_BUFFER_PERIODS 2
    56	#define CAP_PERIOD_MS 100
    57	#define CAP_POLL_US 1000
    58	#define CAP_WAIT_TIMEOUT_US (800 * 1000)
    59	#define CAP_DMIC_VOLUME 160
    60	
    61	struct audio_capture
    62	{
    63	  hal_audio_handle_t audio;
    64	  struct aic_dma_chan_s rx_chan;
    65	  unsigned char *dma_buf;
    66	  unsigned char *read_buf;
    67	  uint32_t period_bytes;
    68	  uint32_t buffer_bytes;
    69	  uint32_t next_read_slot;
    70	  volatile uint32_t next_write_slot;
    71	  volatile uint32_t ready[CAP_BUFFER_PERIODS];
    72	  uint32_t consumed[CAP_BUFFER_PERIODS];
    73	  size_t read_offset;
    74	  bool read_pending;
    75	  bool dma_inited;
    76	  bool dma_registered;
    77	  bool audio_inited;
    78	  bool started;
    79	};
    80	
    81	static struct audio_capture *g_active_capture;
    82	
    83	static uint32_t capture_frame_bytes(unsigned int channels,
    84	                                    unsigned int bits_per_sample)
    85	{
    86	  return channels * (bits_per_sample / 8);
    87	}
    88	
    89	static uint32_t capture_period_bytes(unsigned int sample_rate,
    90	                                     unsigned int channels,
    91	                                     unsigned int bits_per_sample)
    92	{
    93	  uint64_t bytes;
    94	  uint32_t frame_bytes;
    95	
    96	  frame_bytes = capture_frame_bytes(channels, bits_per_sample);
    97	  bytes = (uint64_t)sample_rate * frame_bytes * CAP_PERIOD_MS / 1000;
    98	  if (bytes == 0 || bytes > UINT32_MAX) {
    99	    return 0;
   100	  }
   101	
   102	  /* The DMA buffer must be cache-line aligned and stay on frame boundaries. */
   103	  bytes = (bytes + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE;
   104	  bytes *= CACHE_LINE_SIZE;
   105	  bytes = (bytes + frame_bytes - 1) / frame_bytes;
   106	  bytes *= frame_bytes;
   107	  return bytes > UINT32_MAX ? 0 : (uint32_t)bytes;
   108	}
   109	
   110	static void capture_period_callback(hal_audio_handle_t *haudio)
   111	{
   112	  struct audio_capture *cap = g_active_capture;
   113	  uint32_t slot;
   114	
   115	  if (cap == NULL || haudio != &cap->audio) {
   116	    return;
   117	  }
   118	
   119	  slot = cap->next_write_slot % CAP_BUFFER_PERIODS;
   120	  cap->ready[slot]++;
   121	  cap->next_write_slot++;
   122	}
   123	
   124	static int capture_dma_prepare(struct audio_capture *cap,
   125	                               unsigned int channels)
   126	{
   127	  hal_dma_handle_t *hdma = &cap->rx_chan.hal;
   128	  hal_dma_data_width_e width;
   129	  int ret;
   130	
   131	  ret = drv_dma_init();
   132	  if (ret < 0) {
   133	    syslog(LOG_ERR, "[%s] drv_dma_init failed: %d\n", TAG, ret);
   134	    return ret;
   135	  }
   136	
   137	  hal_dma_handle_init(hdma);
   138	  hdma->regbase = DMA_BASE;
   139	  hdma->init.channel_id = CONFIG_AIC_DMIC_CMD_DMA_CHANNEL;
   140	  hdma->work_mode = DMA_WORK_MODE_CYCLIC;
   141	  hdma->cyclic_period_len = cap->period_bytes;
   142	  hdma->init.direction = DMA_DEVICE_TO_MEMORY;
   143	  hdma->init.src_dev = HAL_DMA_ID_AUDIO;
   144	  hdma->init.src_mode = DMA_MODE_HANDSHAKE;
   145	  hdma->init.src_burst = DMA_XFER_BURST_1;
   146	  hdma->init.src_addr_mode = DMA_ADDR_FIXED_MODE;
   147	  width = channels == 1 ? DMA_DATA_WIDTH_2_BYTES : DMA_DATA_WIDTH_4_BYTES;
   148	  hdma->init.src_data_width = width;
   149	  hdma->init.snk_dev = HAL_DMA_ID_SRAM;
   150	  hdma->init.snk_mode = DMA_MODE_WAIT;
   151	  hdma->init.snk_burst = DMA_XFER_BURST_1;
   152	  hdma->init.snk_addr_mode = DMA_ADDR_LINEAR_MODE;
   153	  hdma->init.snk_data_width = width;
   154	  hdma->init.flag = HAL_HANDLE_ALL_INIT_FLAG;
   155	
   156	  if (hal_dma_init(hdma) != HAL_OK) {
   157	    syslog(LOG_ERR, "[%s] hal_dma_init failed\n", TAG);
   158	    return -EIO;
   159	  }
   160	  cap->dma_inited = true;
   161	
   162	  ret = aic_dma_chan_register(&cap->rx_chan.chan);
   163	  if (ret < 0) {
   164	    syslog(LOG_ERR, "[%s] aic_dma_chan_register failed: %d\n", TAG, ret);
   165	    return ret;
   166	  }
   167	  cap->dma_registered = true;
   168	  return 0;
   169	}
   170	
   171	static int capture_audio_prepare(struct audio_capture *cap,
   172	                                 unsigned int sample_rate,
   173	                                 unsigned int channels)
   174	{
   175	  hal_audio_handle_init(&cap->audio);
   176	  cap->audio.init.samplebits = AUDIO_SAMPLEBITS_16BIT;
   177	  cap->audio.init.samplerate = (hal_audio_samplerate_e)sample_rate;
   178	  cap->audio.init.channel = channels == 1
   179	                              ? AUDIO_CHANNEL_MONO
   180	                              : AUDIO_CHANNEL_STEREO;
   181	  cap->audio.rxdma = &cap->rx_chan.hal;
   182	
   183	  if (hal_audio_init(&cap->audio) != HAL_OK) {
   184	    syslog(LOG_ERR, "[%s] hal_audio_init failed: state=%u err=%u\n",
   185	           TAG, (unsigned int)hal_audio_get_state(&cap->audio),
   186	           (unsigned int)hal_audio_get_error(&cap->audio));
   187	    return -EIO;
   188	  }
   189	  cap->audio_inited = true;
   190	  hal_audio_set_dmic_volume(&cap->audio, CAP_DMIC_VOLUME);
   191	
   192	  if (hal_audio_register_callback(&cap->audio, AUDIO_CB_RX_DMA,
   193	                                  capture_period_callback) != HAL_OK) {
   194	    syslog(LOG_ERR, "[%s] RX callback registration failed\n", TAG);
   195	    return -EIO;
   196	  }
   197	  return 0;
   198	}
   199	
   200	static void capture_stop_internal(struct audio_capture *cap)
   201	{
   202	  if (cap == NULL) {
   203	    return;
   204	  }
   205	
   206	  if (g_active_capture == cap) {
   207	    g_active_capture = NULL;
   208	  }
   209	
   210	  if (cap->started) {
   211	    (void)hal_audio_stop_dmic_dma(&cap->audio);
   212	    cap->started = false;
   213	  }
   214	}
   215	
   216	static void capture_cleanup(struct audio_capture *cap)
   217	{
   218	  if (cap == NULL) {
   219	    return;
   220	  }
   221	
   222	  capture_stop_internal(cap);
   223	
   224	  if (cap->audio_inited) {
   225	    (void)hal_audio_unregister_callback(&cap->audio, AUDIO_CB_RX_DMA, NULL);
   226	    (void)hal_audio_deinit(&cap->audio);
   227	    cap->audio_inited = false;
   228	  }
   229	
   230	  if (cap->dma_registered) {
   231	    aic_dma_chan_unregister(&cap->rx_chan.chan);
   232	    cap->dma_registered = false;
   233	  }
   234	
   235	  if (cap->dma_inited) {
   236	    (void)hal_dma_deinit(&cap->rx_chan.hal);
   237	    cap->dma_inited = false;
   238	  }
   239	
   240	  free(cap->read_buf);
   241	  free(cap->dma_buf);
   242	  cap->read_buf = NULL;
   243	  cap->dma_buf = NULL;
   244	}
   245	
   246	audio_capture_t *audio_capture_open(const char *dev_path,
   247	                                     unsigned int sample_rate,
   248	                                     unsigned int channels,
   249	                                     unsigned int bits_per_sample)
   250	{
   251	  struct audio_capture *cap;
   252	  uint32_t period_bytes;
   253	  int ret;
   254	
   255	  (void)dev_path;
   256	
   257	  if ((channels != 1 && channels != 2) ||
   258	      bits_per_sample != 16 ||
   259	      sample_rate == 0) {
   260	    return NULL;
   261	  }
   262	
   263	  period_bytes = capture_period_bytes(sample_rate, channels,
   264	                                      bits_per_sample);
   265	  if (period_bytes == 0) {
   266	    return NULL;
   267	  }
   268	
   269	  cap = calloc(1, sizeof(*cap));
   270	  if (cap == NULL) {
   271	    return NULL;
   272	  }
   273	
   274	  cap->period_bytes = period_bytes;
   275	  cap->buffer_bytes = period_bytes * CAP_BUFFER_PERIODS;
   276	  cap->dma_buf = memalign(CACHE_LINE_SIZE, cap->buffer_bytes);
   277	  cap->read_buf = memalign(CACHE_LINE_SIZE, period_bytes);
   278	  if (cap->dma_buf == NULL || cap->read_buf == NULL) {
   279	    capture_cleanup(cap);
   280	    free(cap);
   281	    return NULL;
   282	  }
   283	
   284	  memset(cap->dma_buf, 0, cap->buffer_bytes);
   285	  memset(cap->read_buf, 0, period_bytes);
   286	  up_invalidate_dcache((uintptr_t)cap->dma_buf,
   287	                       (uintptr_t)cap->dma_buf + cap->buffer_bytes);
   288	
   289	  ret = capture_dma_prepare(cap, channels);
   290	  if (ret < 0) {
   291	    capture_cleanup(cap);
   292	    free(cap);
   293	    return NULL;
   294	  }
   295	
   296	  ret = capture_audio_prepare(cap, sample_rate, channels);
   297	  if (ret < 0) {
   298	    capture_cleanup(cap);
   299	    free(cap);
   300	    return NULL;
   301	  }
   302	
   303	  syslog(LOG_INFO, "[%s] opened DMIC (%uHz %uch %ubit period=%u dma_ch=%d)\n",
   304	         TAG, sample_rate, channels, bits_per_sample,
   305	         (unsigned int)period_bytes, CONFIG_AIC_DMIC_CMD_DMA_CHANNEL);
   306	  return cap;
   307	}
   308	
   309	int audio_capture_start(audio_capture_t *cap)
   310	{
   311	  if (cap == NULL || !cap->audio_inited || cap->started) {
   312	    return -EINVAL;
   313	  }
   314	
   315	  memset((void *)cap->ready, 0, sizeof(cap->ready));
   316	  memset(cap->consumed, 0, sizeof(cap->consumed));
   317	  cap->next_read_slot = 0;
   318	  cap->next_write_slot = 0;
   319	  cap->read_offset = 0;
   320	  cap->read_pending = false;
   321	  memset(cap->read_buf, 0, cap->period_bytes);
   322	  g_active_capture = cap;
   323	
   324	  if (hal_audio_receive_dmic_dma(&cap->audio, cap->dma_buf,
   325	                                 cap->buffer_bytes,
   326	                                 cap->period_bytes) != HAL_OK) {
   327	    g_active_capture = NULL;
   328	    syslog(LOG_ERR, "[%s] hal_audio_receive_dmic_dma failed\n", TAG);
   329	    return -EIO;
   330	  }
   331	
   332	  cap->started = true;
   333	  syslog(LOG_INFO, "[%s] capture started\n", TAG);
   334	  return 0;
   335	}
   336	
   337	int audio_capture_stop(audio_capture_t *cap)
   338	{
   339	  if (cap == NULL) {
   340	    return -EINVAL;
   341	  }
   342	
   343	  capture_stop_internal(cap);
   344	  return 0;
   345	}
   346	
   347	int audio_capture_read(audio_capture_t *cap, void *buf, size_t len)
   348	{
   349	  size_t copied = 0;
   350	  unsigned int waited_us = 0;
   351	
   352	  if (cap == NULL || buf == NULL || len == 0) {
   353	    return -EINVAL;
   354	  }
   355	
   356	  while (copied < len) {
   357	    size_t available;
   358	
   359	    if (cap->read_pending) {
   360	      available = cap->period_bytes - cap->read_offset;
   361	      if (available > len - copied) {
   362	        available = len - copied;
   363	      }
   364	      memcpy((unsigned char *)buf + copied,
   365	             cap->read_buf + cap->read_offset, available);
   366	      cap->read_offset += available;
   367	      copied += available;
   368	      if (cap->read_offset == cap->period_bytes) {
   369	        cap->read_offset = 0;
   370	        cap->read_pending = false;
   371	      }
   372	      continue;
   373	    }
   374	
   375	    if (!cap->started) {
   376	      return copied > 0 ? (int)copied : -EPIPE;
   377	    }
   378	
   379	    {
   380	      uint32_t slot = cap->next_read_slot % CAP_BUFFER_PERIODS;
   381	      uint32_t ready = cap->ready[slot];
   382	      uint32_t consumed = cap->consumed[slot];
   383	
   384	      if (ready != consumed) {
   385	        if (ready - consumed > 1) {
   386	          /* The reader fell behind; keep the newest complete period. */
   387	          consumed = ready - 1;
   388	          cap->consumed[slot] = consumed;
   389	          syslog(LOG_WARNING, "[%s] capture overrun, dropping old period\n",
   390	                 TAG);
   391	        }
   392	
   393	        up_invalidate_dcache(
   394	            (uintptr_t)(cap->dma_buf + slot * cap->period_bytes),
   395	            (uintptr_t)(cap->dma_buf + (slot + 1) * cap->period_bytes));
   396	        memcpy(cap->read_buf,
   397	               cap->dma_buf + slot * cap->period_bytes,
   398	               cap->period_bytes);
   399	        cap->consumed[slot] = consumed + 1;
   400	        cap->next_read_slot++;
   401	        cap->read_pending = true;
   402	        waited_us = 0;
   403	        continue;
   404	      }
   405	    }
   406	
   407	    if (waited_us >= CAP_WAIT_TIMEOUT_US) {
   408	      syslog(LOG_ERR, "[%s] timeout waiting for DMIC period\n", TAG);
   409	      capture_stop_internal(cap);
   410	      return copied > 0 ? (int)copied : -ETIMEDOUT;
   411	    }
   412	
   413	    usleep(CAP_POLL_US);
   414	    waited_us += CAP_POLL_US;
   415	  }
   416	
   417	  return (int)copied;
   418	}
   419	
   420	void audio_capture_close(audio_capture_t *cap)
   421	{
   422	  if (cap == NULL) {
   423	    return;
   424	  }
   425	
   426	  capture_cleanup(cap);
   427	  free(cap);
   428	}
