    44	#define PB_TMP_TEMPLATE "/tmp/velaclaw_tts_XXXXXX"
    45	#define PB_IDLE_MIN_WAIT_MS 7000
    46	#define PB_IDLE_EXTRA_MS 2500
    47	#define AUDIO_PB_NXPLAYER_STATE_IDLE 0
    48	
    49	struct audio_playback
    50	{
    51	  int tmp_fd;
    52	  size_t total_written;
    53	  unsigned int sample_rate;
    54	  unsigned int channels;
    55	  unsigned int bits_per_sample;
    56	  int write_error;
    57	  bool use_memfd;
