    63	
    64	static uint64_t audio_pb_now_ms(void)
    65	{
    66	  struct timespec ts;
    67	
    68	#ifdef CLOCK_MONOTONIC
    69	  clock_gettime(CLOCK_MONOTONIC, &ts);
    70	#else
    71	  clock_gettime(CLOCK_REALTIME, &ts);
    72	#endif
    73	  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
    74	}
    75	
    76	static uint64_t audio_playback_pcm_ms(const audio_playback_t *pb)
    77	{
    78	  uint64_t bytes_per_second;
    79	
    80	  if (pb == NULL || pb->sample_rate == 0 || pb->channels == 0 ||
    81	      pb->bits_per_sample == 0) {
    82	    return 0;
    83	  }
    84	
    85	  bytes_per_second = (uint64_t)pb->sample_rate * pb->channels *
    86	                     (pb->bits_per_sample / 8);
    87	  return (uint64_t)pb->total_written * 1000 / bytes_per_second;
    88	}
    89	
    90	#ifdef CONFIG_SYSTEM_NXPLAYER
    91	static int audio_playback_wait_idle(struct nxplayer_s *player,
    92	                                    const audio_playback_t *pb,
    93	                                    uint64_t start_ms)
    94	{
    95	  uint64_t limit_ms;
    96	
    97	  if (player == NULL || pb == NULL) {
    98	    return -EINVAL;
    99	  }
   100	
   101	  limit_ms = audio_playback_pcm_ms(pb) + PB_IDLE_EXTRA_MS;
   102	  if (limit_ms < PB_IDLE_MIN_WAIT_MS) {
   103	    limit_ms = PB_IDLE_MIN_WAIT_MS;
   104	  }
   105	
   106	  for (;;) {
   107	    int state;
   108	
   109	    pthread_mutex_lock(&player->mutex);
   110	    state = player->state;
   111	    pthread_mutex_unlock(&player->mutex);
   112	    if (state == AUDIO_PB_NXPLAYER_STATE_IDLE) {
   113	      return 0;
   114	    }
   115	    if (audio_pb_now_ms() - start_ms > limit_ms) {
   116	      syslog(LOG_ERR,
   117	             "[%s] playback idle timeout (audio=%llums bytes=%zu state=%d)\n",
   118	             TAG, (unsigned long long)audio_playback_pcm_ms(pb),
   119	             pb->total_written, state);
   120	      return -ETIMEDOUT;
   121	    }
   122	    usleep(20 * 1000);
   123	  }
   124	}
   125	#endif
   126	
   127	audio_playback_t *audio_playback_open(const char *dev_path,
   128	                                      unsigned int sample_rate,
   129	                                      unsigned int channels,
   130	                                      unsigned int bits_per_sample)
   131	{
