    36	static int mkdirs(const char *path)
    37	{
    38	    char tmp[256];
    39	    snprintf(tmp, sizeof(tmp), "%s", path);
    40	    for (char *p = tmp + 1; *p; p++) {
    41	        if (*p == '/') {
    42	            *p = '\0';
    43	            mkdir(tmp, 0700);
    44	            *p = '/';
    45	        }
    46	    }
    47	    mkdir(tmp, 0700);
    48	    return OK;
    49	}
