    51	static cJSON *load_json(void)
    52	{
    53	    FILE *f = fopen(VELACLAW_CONFIG_FILE, "r");
    54	    if (!f) return cJSON_CreateObject();
    55	
    56	    fseek(f, 0, SEEK_END);
    57	    long sz = ftell(f);
    58	    fseek(f, 0, SEEK_SET);
    59	
    60	    if (sz <= 0) { fclose(f); return cJSON_CreateObject(); }
    61	
    62	    char *buf = (char *)malloc((size_t)(sz + 1));
    63	    if (!buf) { fclose(f); return cJSON_CreateObject(); }
    64	
    65	    size_t n = fread(buf, 1, (size_t)sz, f);
    66	    buf[n] = '\0';
    67	    fclose(f);
    68	
    69	    cJSON *root = cJSON_Parse(buf);
    70	    free(buf);
    71	    return root ? root : cJSON_CreateObject();
    72	}
