    74	static int write_all(int fd, const char *buf, size_t len)
    75	{
    76	    size_t off = 0;
    77	
    78	    while (off < len) {
    79	        ssize_t n = write(fd, buf + off, len - off);
    80	        if (n < 0) {
    81	            if (errno == EINTR) {
    82	                continue;
    83	            }
    84	            return ERROR;
    85	        }
    86	        if (n == 0) {
    87	            return ERROR;
    88	        }
    89	        off += (size_t)n;
    90	    }
    91	
    92	    return OK;
    93	}
