    95	static int seed_default_config(void)
    96	{
    97	    struct stat st;
    98	    char tmp_path[sizeof(VELACLAW_CONFIG_FILE) + 8];
    99	    FILE *src;
   100	    int fd;
   101	    int ret = ERROR;
   102	    char buf[256];
   103	    size_t n;
   104	
   105	    if (stat(VELACLAW_CONFIG_FILE, &st) == 0 && st.st_size > 0) {
   106	        return OK;
   107	    }
   108	
   109	    src = fopen(VELACLAW_DEFAULT_CONFIG_FILE, "r");
   110	    if (!src) {
   111	        syslog(LOG_INFO, "[%s] No bundled default config at %s\n",
   112	            TAG, VELACLAW_DEFAULT_CONFIG_FILE);
   113	        return ERROR;
   114	    }
   115	
   116	    snprintf(tmp_path, sizeof(tmp_path), "%s.tmp", VELACLAW_CONFIG_FILE);
   117	    fd = open(tmp_path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
   118	    if (fd < 0) {
   119	        fclose(src);
   120	        return ERROR;
   121	    }
   122	
   123	    while ((n = fread(buf, 1, sizeof(buf), src)) > 0) {
   124	        if (write_all(fd, buf, n) != OK) {
   125	            goto out;
   126	        }
   127	    }
   128	
   129	    if (ferror(src) != 0 || fsync(fd) < 0) {
   130	        goto out;
   131	    }
   132	
   133	    if (close(fd) < 0) {
   134	        fd = -1;
   135	        goto out;
   136	    }
   137	    fd = -1;
   138	
   139	    if (rename(tmp_path, VELACLAW_CONFIG_FILE) < 0) {
   140	        goto out;
   141	    }
   142	
   143	    ret = OK;
   144	    syslog(LOG_INFO, "[%s] Seeded default config from %s\n",
   145	        TAG, VELACLAW_DEFAULT_CONFIG_FILE);
   146	
   147	out:
   148	    if (fd >= 0) {
   149	        close(fd);
   150	    }
   151	    fclose(src);
   152	    if (ret != OK) {
   153	        unlink(tmp_path);
   154	    }
   155	    return ret;
   156	}
