   158	static int save_json(cJSON *root)
   159	{
   160	    char *str = cJSON_PrintUnformatted(root);
   161	    if (!str) return ERROR;
   162	
   163	    /* Use open() with explicit 0600 to ensure config file is owner-only.
   164	     * fopen("w") inherits umask which may be too permissive. */
   165	    int fd = open(VELACLAW_CONFIG_FILE,
   166	                  O_WRONLY | O_CREAT | O_TRUNC, 0600);
   167	    if (fd < 0) { free(str); return ERROR; }
   168	
   169	    FILE *f = fdopen(fd, "w");
   170	    if (!f) { close(fd); free(str); return ERROR; }
   171	    fputs(str, f);
   172	    fclose(f);
   173	    free(str);
   174	    return OK;
   175	}
