   192	int claw_config_get(const char *key, char *buf, size_t buf_size)
   193	{
   194	    pthread_mutex_lock(&s_lock);
   195	    cJSON *root = load_json();
   196	    cJSON *item = cJSON_GetObjectItem(root, key);
   197	    int ret = ERROR;
   198	    if (item && cJSON_IsString(item) && item->valuestring[0] != '\0') {
   199	        strncpy(buf, item->valuestring, buf_size - 1);
   200	        buf[buf_size - 1] = '\0';
   201	        ret = OK;
   202	    }
   203	    cJSON_Delete(root);
   204	    pthread_mutex_unlock(&s_lock);
   205	    return ret;
   206	}
   207	
   208	int claw_config_set(const char *key, const char *value)
   209	{
   210	    pthread_mutex_lock(&s_lock);
   211	    cJSON *root = load_json();
   212	    cJSON_DeleteItemFromObject(root, key);
   213	    cJSON_AddStringToObject(root, key, value);
   214	    int ret = save_json(root);
   215	    cJSON_Delete(root);
   216	    pthread_mutex_unlock(&s_lock);
   217	    return ret;
   218	}
