   220	int config_del(const char *key)
   221	{
   222	    pthread_mutex_lock(&s_lock);
   223	    cJSON *root = load_json();
   224	    cJSON_DeleteItemFromObject(root, key);
   225	    int ret = save_json(root);
   226	    cJSON_Delete(root);
   227	    pthread_mutex_unlock(&s_lock);
   228	    return ret;
   229	}
