    65	static int msg_queue_push(msg_queue_t *queue, const velaclaw_msg_t *msg,
    66	                          uint32_t timeout_ms)
    67	{
    68	    struct timespec ts;
    69	
    70	    pthread_mutex_lock(&queue->lock);
    71	
    72	    if (queue->count >= VELACLAW_BUS_QUEUE_LEN) {
    73	        if (timeout_ms == 0) {
    74	            pthread_mutex_unlock(&queue->lock);
    75	            return ERROR;
    76	        }
    77	
    78	        clock_gettime(CLOCK_REALTIME, &ts);
    79	        ts.tv_sec += (time_t)(timeout_ms / 1000);
    80	        ts.tv_nsec += (long)((timeout_ms % 1000) * 1000000L);
    81	        if (ts.tv_nsec >= 1000000000L) {
    82	            ts.tv_sec++;
    83	            ts.tv_nsec -= 1000000000L;
    84	        }
    85	
    86	        /* Wait for space */
    87	        while (queue->count >= VELACLAW_BUS_QUEUE_LEN) {
    88	            if (pthread_cond_timedwait(&queue->not_full, &queue->lock, &ts) != 0) {
    89	                pthread_mutex_unlock(&queue->lock);
    90	                syslog(LOG_WARNING, "[%s] Queue full, dropping message\n", TAG);
    91	                return ERROR;
    92	            }
    93	        }
    94	    }
    95	
    96	    queue->items[queue->tail] = *msg;
    97	    queue->tail = (queue->tail + 1) % VELACLAW_BUS_QUEUE_LEN;
    98	    queue->count++;
    99	
   100	    pthread_cond_signal(&queue->not_empty);
   101	    pthread_mutex_unlock(&queue->lock);
   102	    return OK;
   103	}
