   105	static int msg_queue_pop(msg_queue_t *queue, velaclaw_msg_t *msg,
   106	                         uint32_t timeout_ms)
   107	{
   108	    struct timespec ts;
   109	
   110	    pthread_mutex_lock(&queue->lock);
   111	
   112	    while (queue->count == 0) {
   113	        if (g_bus_shutdown) {
   114	            pthread_mutex_unlock(&queue->lock);
   115	            return ERROR;
   116	        }
   117	        if (timeout_ms == UINT32_MAX) {
   118	            pthread_cond_wait(&queue->not_empty, &queue->lock);
   119	        } else {
   120	            clock_gettime(CLOCK_REALTIME, &ts);
   121	            ts.tv_sec += (time_t)(timeout_ms / 1000);
   122	            ts.tv_nsec += (long)((timeout_ms % 1000) * 1000000L);
   123	            if (ts.tv_nsec >= 1000000000L) {
   124	                ts.tv_sec++;
   125	                ts.tv_nsec -= 1000000000L;
   126	            }
   127	
   128	            if (pthread_cond_timedwait(&queue->not_empty, &queue->lock, &ts) != 0) {
   129	                pthread_mutex_unlock(&queue->lock);
   130	                return ERROR;
   131	            }
   132	        }
   133	    }
   134	
   135	    *msg = queue->items[queue->head];
   136	    queue->head = (queue->head + 1) % VELACLAW_BUS_QUEUE_LEN;
   137	    queue->count--;
   138	
   139	    pthread_cond_signal(&queue->not_full);
   140	    pthread_mutex_unlock(&queue->lock);
   141	    return OK;
   142	}
