   144	static void msg_queue_clear_channel(msg_queue_t *queue, const char *channel)
   145	{
   146	    velaclaw_msg_t kept[VELACLAW_BUS_QUEUE_LEN];
   147	    int kept_count = 0;
   148	    int dropped = 0;
   149	
   150	    if (queue == NULL || channel == NULL || channel[0] == '\0') {
   151	        return;
   152	    }
   153	
   154	    pthread_mutex_lock(&queue->lock);
   155	    while (queue->count > 0) {
   156	        velaclaw_msg_t msg = queue->items[queue->head];
   157	
   158	        memset(&queue->items[queue->head], 0,
   159	               sizeof(queue->items[queue->head]));
   160	        queue->head = (queue->head + 1) % VELACLAW_BUS_QUEUE_LEN;
   161	        queue->count--;
   162	
   163	        msg.channel[sizeof(msg.channel) - 1] = '\0';
   164	        if (strcmp(msg.channel, channel) == 0) {
   165	            free(msg.content);
   166	            free(msg.image_b64);
   167	            dropped++;
   168	        } else if (kept_count < VELACLAW_BUS_QUEUE_LEN) {
   169	            kept[kept_count++] = msg;
   170	        } else {
   171	            free(msg.content);
   172	            free(msg.image_b64);
   173	            dropped++;
   174	        }
   175	    }
   176	
   177	    queue->head = 0;
   178	    queue->tail = 0;
   179	    queue->count = 0;
   180	    for (int i = 0; i < kept_count; i++) {
   181	        queue->items[queue->tail] = kept[i];
   182	        queue->tail = (queue->tail + 1) % VELACLAW_BUS_QUEUE_LEN;
   183	        queue->count++;
   184	    }
   185	
   186	    pthread_cond_broadcast(&queue->not_full);
   187	    pthread_mutex_unlock(&queue->lock);
   188	
