   321	  uint32_t new_mask,
   322	  int32_t adc_raw)
   323	{
   324	  size_t count = 0;
   325	  enum aic_button_id id;
   326	
   327	  for (id = AIC_BUTTON_UP; id <= AIC_BUTTON_WAKEUP; id++)
   328	    {
   329	      uint32_t bit = aic_button_bit(id);
   330	      bool old_pressed = (old_mask & bit) != 0;
   331	      bool new_pressed = (new_mask & bit) != 0;
   332	
   333	      if (old_pressed != new_pressed)
   334	        {
   335	          struct aic_button_event event;
   336	
   337	          memset(&event, 0, sizeof(event));
   338	          event.id = id;
   339	          event.action = new_pressed ? AIC_BUTTON_PRESSED :
   340	                         AIC_BUTTON_RELEASED;
   341	          event.state_mask = new_mask;
   342	          event.adc_raw = adc_raw;
   343	          if (aic_button_queue_push_locked(&event) == 0)
   344	            {
   345	              count++;
   346	            }
   347	        }
   348	    }
   349	
   350	  return count;
   351	}
