  1033	int aic_button_inject(enum aic_button_id id)
  1034	{
  1035	  struct aic_button_event event;
  1036	  uint32_t bit;
  1037	  uint32_t base_mask;
  1038	  uint8_t queue_count;
  1039	  int ret;
  1040	
  1041	  if (!aic_button_valid_id(id))
  1042	    {
  1043	      return -EINVAL;
  1044	    }
  1045	
  1046	  ret = aic_button_service_start();
  1047	  if (ret < 0)
  1048	    {
  1049	      return ret;
  1050	    }
  1051	
  1052	  bit = aic_button_bit(id);
  1053	
  1054	  pthread_mutex_lock(&g_button_lock);
  1055	  base_mask = g_button.have_state ? g_button.stable_mask :
  1056	              (g_button.have_sample ? g_button.last_sample.state_mask : 0);
  1057	
  1058	  queue_count = g_button.queue_head >= g_button.queue_tail ?
  1059	                g_button.queue_head - g_button.queue_tail :
  1060	                AIC_BUTTON_QUEUE_SIZE + g_button.queue_head -
  1061	                g_button.queue_tail;
  1062	  if (queue_count > AIC_BUTTON_QUEUE_SIZE - 1 - 2)
  1063	    {
  1064	      pthread_mutex_unlock(&g_button_lock);
  1065	      return -ENOSPC;
  1066	    }
  1067	
  1068	  memset(&event, 0, sizeof(event));
  1069	  event.id = id;
  1070	  event.adc_raw = -1;
  1071	  event.action = AIC_BUTTON_PRESSED;
  1072	  event.state_mask = base_mask | bit;
  1073	  (void)aic_button_queue_push_locked(&event);
  1074	
  1075	  event.action = AIC_BUTTON_RELEASED;
  1076	  event.state_mask = base_mask & ~bit;
  1077	  (void)aic_button_queue_push_locked(&event);
  1078	  pthread_mutex_unlock(&g_button_lock);
  1079	  return 0;
  1080	}
