   124	  int ret;
   125	
   126	  if (argc > argi)
   127	    {
   128	      count = strtoul(argv[argi++], NULL, 0);
   129	    }
   130	
   131	  if (argc > argi)
   132	    {
   133	      interval_ms = strtoul(argv[argi++], NULL, 0);
   134	    }
   135	
   136	  ret = aic_button_init(NULL);
   137	  if (ret < 0)
   138	    {
   139	      button_print_error("init", ret);
