   170	static int button_run_listen(int argc, char *argv[], int argi)
   171	{
   172	  uint32_t timeout_ms = AIC_BUTTON_TIMEOUT_FOREVER;
   173	  uint32_t elapsed_ms = 0;
   174	  bool subscribed = false;
   175	  int ret;
   176	
   177	  if (argc > argi)
   178	    {
   179	      timeout_ms = (uint32_t)strtoul(argv[argi], NULL, 0);
   180	      if (timeout_ms == 0)
   181	        {
   182	          timeout_ms = AIC_BUTTON_TIMEOUT_FOREVER;
   183	        }
   184	    }
   185	
   186	  ret = aic_button_subscribe(button_print_event, NULL);
   187	  if (ret < 0 && ret != -EALREADY)
   188	    {
   189	      button_print_error("subscribe", ret);
   190	      return 1;
   191	    }
   192	
   193	  subscribed = ret == 0;
   194	  ret = aic_button_service_start();
   195	  if (ret < 0)
   196	    {
   197	      if (subscribed)
   198	        {
   199	          aic_button_unsubscribe(button_print_event, NULL);
   200	        }
   201	
   202	      button_print_error("service_start", ret);
   203	      return 1;
   204	    }
   205	
   206	  printf("button: listening, driver=psadc_poll psadc_ch=%d wakeup=%s interval=%dms\n",
   207	         CONFIG_AIC_INPUT_BUTTON_PSADC_CH,
   208	         CONFIG_AIC_INPUT_BUTTON_WAKEUP_PIN,
   209	         CONFIG_AIC_INPUT_BUTTON_POLL_INTERVAL_MS);
   210	
   211	  while (timeout_ms == AIC_BUTTON_TIMEOUT_FOREVER ||
   212	         elapsed_ms < timeout_ms)
   213	    {
   214	      usleep((useconds_t)CONFIG_AIC_INPUT_BUTTON_POLL_INTERVAL_MS * 1000u);
   215	
   216	      if (timeout_ms != AIC_BUTTON_TIMEOUT_FOREVER)
   217	        {
   218	          if (elapsed_ms >
   219	              UINT32_MAX - CONFIG_AIC_INPUT_BUTTON_POLL_INTERVAL_MS)
   220	            {
   221	              elapsed_ms = UINT32_MAX;
   222	            }
   223	          else
   224	            {
   225	              elapsed_ms += CONFIG_AIC_INPUT_BUTTON_POLL_INTERVAL_MS;
   226	            }
   227	        }
   228	    }
   229	
   230	  if (subscribed)
   231	    {
   232	      aic_button_unsubscribe(button_print_event, NULL);
   233	    }
   234	
   235	  return 0;
   236	}
