   306	
   307	  if (argc <= argi)
   308	    {
   309	      button_usage();
   310	      return 1;
   311	    }
   312	
   313	  cmd = argv[argi++];
   314	
   315	  if (strcmp(cmd, "sample") == 0)
   316	    {
   317	      return button_run_sample();
   318	    }
   319	  else if (strcmp(cmd, "raw") == 0)
   320	    {
   321	      return button_run_raw(argc, argv, argi);
   322	    }
   323	  else if (strcmp(cmd, "listen") == 0)
   324	    {
   325	      return button_run_listen(argc, argv, argi);
   326	    }
   327	  else if (strcmp(cmd, "thresholds") == 0)
   328	    {
   329	      return button_run_thresholds();
   330	    }
   331	  else if (strcmp(cmd, "status") == 0)
   332	    {
   333	      return button_run_status();
   334	    }
   335	  else if (strcmp(cmd, "up") == 0)
   336	    {
   337	      return button_run_inject(AIC_BUTTON_UP);
   338	    }
   339	  else if (strcmp(cmd, "down") == 0)
   340	    {
   341	      return button_run_inject(AIC_BUTTON_DOWN);
