    15	/* D13X PSADC controller register map. */
    16	#define AIC_PSADC_CLK_RATE      40000000UL
    17	
    18	#define PSADC_MCR               0x000
    19	#define PSADC_TCR               0x004
    20	#define PSADC_NODE1             0x008
    21	#define PSADC_MSR               0x010
    22	#define PSADC_Q1FCR             0x020
    23	#define PSADC_Q1FDR             0x040
    24	
    25	#define PSADC_MCR_Q1_TRIGS      BIT(22)
    26	#define PSADC_MCR_Q1_INTE       BIT(18)
    27	#define PSADC_MCR_QUE_COMB      BIT(1)
    28	#define PSADC_MCR_EN            BIT(0)
    29	
    30	#define PSADC_MSR_Q1_FERR       BIT(2)
    31	#define PSADC_MSR_Q1_INT        BIT(0)
    32	
    33	#define PSADC_FCR_DCNT_MASK     GENMASK(28, 24)
    34	#define PSADC_FCR_DCNT_SHIFT    24
    35	#define PSADC_FCR_DRTH_SHIFT    8
    36	#define PSADC_FCR_FIFO_ERRIE    BIT(3)
    37	#define PSADC_FCR_FIFO_RDYIE    BIT(1)
    38	#define PSADC_FCR_FIFO_FLUSH    BIT(0)
    39	#define PSADC_FCR_UF_STS        BIT(17)
    40	#define PSADC_FCR_OF_STS        BIT(16)
    41	
    42	#define PSADC_Q1FDR_DATA_MASK   GENMASK(11, 0)
    43	#define PSADC_Q1_NODE_MASK      GENMASK(3, 0)
    44	
    45	static bool g_psadc_initialized;
    46	
    47	static inline void psadc_writel(u32 value, u32 offset)
    48	{
    49	  writel(value, PSADC_BASE + offset);
    50	}
    51	
    52	static inline u32 psadc_readl(u32 offset)
    53	{
    54	  return readl(PSADC_BASE + offset);
    55	}
    56	
    57	static void psadc_fifo_flush(void)
    58	{
    59	  u32 value = psadc_readl(PSADC_Q1FCR);
    60	
    61	  if (value & PSADC_FCR_UF_STS)
    62	    {
    63	      syslog(LOG_ERR, "PSADC Q1 FIFO underflow: FCR=%#x\n", value);
    64	    }
    65	
    66	  if (value & PSADC_FCR_OF_STS)
    67	    {
    68	      syslog(LOG_ERR, "PSADC Q1 FIFO overflow: FCR=%#x\n", value);
    69	    }
    70	
    71	  psadc_writel(value | PSADC_FCR_FIFO_FLUSH, PSADC_Q1FCR);
    72	}
