    74	static void psadc_clear_status(void)
    75	{
    76	  u32 status = psadc_readl(PSADC_MSR);
    77	
    78	  if (status != 0)
    79	    {
    80	      psadc_writel(status, PSADC_MSR);
    81	    }
    82	}
    83	
    84	static void psadc_set_q1_channel(u32 channel)
    85	{
    86	  psadc_writel(channel & PSADC_Q1_NODE_MASK, PSADC_NODE1);
    87	}
