    92	         "PSADC Q1 timeout: MCR=%#x MSR=%#x NODE1=%#x TCR=%#x "
    93	         "Q1FCR=%#x Q1DCNT=%u\n",
    94	         psadc_readl(PSADC_MCR),
    95	         psadc_readl(PSADC_MSR),
    96	         psadc_readl(PSADC_NODE1),
    97	         psadc_readl(PSADC_TCR),
    98	         psadc_readl(PSADC_Q1FCR),
