   103	int hal_psadc_init(void)
   104	{
   105	  int ret;
   106	
   107	  if (g_psadc_initialized)
   108	    {
   109	      return 0;
   110	    }
   111	
   112	  ret = hal_clk_set_freq(CLK_PSADC, AIC_PSADC_CLK_RATE);
   113	  if (ret < 0)
   114	    {
   115	      return ret;
   116	    }
   117	
   118	  ret = hal_clk_enable_deassertrst(CLK_PSADC);
   119	  if (ret < 0)
   120	    {
   121	      return ret;
   122	    }
   123	
   124	  /*
   125	   * QC is configured as one Q1 node. The threshold is one sample, matching
   126	   * the RT-Thread test path used on D13X.
   127	   */
   128	  psadc_writel(0, PSADC_NODE1);
   129	  psadc_writel(0, PSADC_TCR);
   130	  psadc_writel(PSADC_FCR_FIFO_ERRIE |
   131	               PSADC_FCR_FIFO_RDYIE |
   132	               (1U << PSADC_FCR_DRTH_SHIFT), PSADC_Q1FCR);
   133	  psadc_fifo_flush();
   134	  psadc_clear_status();
   135	  psadc_writel(PSADC_MCR_QUE_COMB | PSADC_MCR_EN |
   136	               PSADC_MCR_Q1_INTE, PSADC_MCR);
   137	
   138	  g_psadc_initialized = true;
   139	  return 0;
   140	}
   141	
   142	void hal_psadc_deinit(void)
   143	{
   144	  if (!g_psadc_initialized)
   145	    {
   146	      return;
   147	    }
   148	
   149	  psadc_writel(0, PSADC_MCR);
   150	  psadc_fifo_flush();
   151	  psadc_clear_status();
   152	  (void)hal_clk_disable_assertrst(CLK_PSADC);
   153	  g_psadc_initialized = false;
   154	}
