   156	int hal_psadc_read_channel_poll(u32 channel, u32 *value, u32 timeout_ms)
   157	{
   158	  u32 status;
   159	  u64 start_us;
   160	  u64 timeout_us;
   161	  int ret;
   162	
   163	  if (value == NULL)
   164	    {
   165	      return -EINVAL;
   166	    }
   167	
   168	  if (channel >= AIC_PSADC_CHANNEL_COUNT)
   169	    {
   170	      return -EINVAL;
   171	    }
   172	
   173	  ret = hal_psadc_init();
   174	  if (ret < 0)
   175	    {
   176	      return ret;
   177	    }
   178	
   179	  /*
   180	   * The button service uses one Q1 node. Rewriting NODE1 on each read keeps
   181	   * this helper deterministic if another caller changes the selected input.
   182	   */
   183	  psadc_set_q1_channel(channel);
   184	  psadc_writel(0, PSADC_TCR);
   185	  psadc_fifo_flush();
   186	  psadc_clear_status();
   187	
   188	  status = psadc_readl(PSADC_MCR);
   189	  psadc_writel(status | PSADC_MCR_Q1_TRIGS, PSADC_MCR);
   190	
   191	  start_us = aic_get_time_us();
   192	  timeout_us = (u64)timeout_ms * 1000ULL;
   193	  for (;;)
   194	    {
   195	      status = psadc_readl(PSADC_MSR);
   196	
   197	      if (status != 0)
   198	        {
   199	          psadc_writel(status, PSADC_MSR);
   200	        }
   201	
   202	      if (status & PSADC_MSR_Q1_INT)
   203	        {
   204	          *value = psadc_readl(PSADC_Q1FDR) & PSADC_Q1FDR_DATA_MASK;
   205	          return 0;
   206	        }
   207	
   208	      if (status & PSADC_MSR_Q1_FERR)
   209	        {
   210	          psadc_fifo_flush();
   211	        }
   212	
   213	      if (timeout_ms != 0 &&
   214	          (aic_get_time_us() - start_us) >= timeout_us)
   215	        {
   216	          psadc_dump_timeout();
   217	          return -ETIMEDOUT;
   218	        }
   219	
   220	      aic_udelay(1);
   221	    }
   222	}

