    96	static int bt_ext_uart_configure(int fd, unsigned int baud)
    97	{
    98	  struct termios tio;
    99	  speed_t speed = bt_ext_speed_from_baud(baud);
   100	
   101	  if (tcgetattr(fd, &tio) != 0)
   102	    {
   103	      return -errno;
   104	    }
   105	
   106	  tio.c_cflag &= ~(PARENB | CSTOPB | CSIZE);
   107	  tio.c_cflag |= CS8 | CREAD | CLOCAL;
   108	  tio.c_iflag &= ~(IXON | IXOFF | IXANY | ICRNL | INLCR);
   109	  tio.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
   110	  tio.c_oflag &= ~OPOST;
   111	  tio.c_cc[VMIN] = 0;
   112	  tio.c_cc[VTIME] = 0;
   113	
   114	  if (cfsetispeed(&tio, speed) != 0 || cfsetospeed(&tio, speed) != 0)
   115	    {
   116	      return -errno;
   117	    }
   118	
   119	  if (tcsetattr(fd, TCSANOW, &tio) != 0)
   120	    {
   121	      return -errno;
   122	    }
   123	
   124	  tcflush(fd, TCIOFLUSH);
   125	  return 0;
   126	}
