   128	static int bt_ext_write_all(int fd, const uint8_t *data, size_t len)
   129	{
   130	  size_t off = 0;
   131	
   132	  while (off < len)
   133	    {
   134	      ssize_t n = write(fd, data + off, len - off);
   135	
   136	      if (n < 0)
   137	        {
   138	          if (errno == EINTR || errno == EAGAIN)
   139	            {
   140	              continue;
   141	            }
   142	
   143	          return -errno;
   144	        }
   145	
   146	      if (n == 0)
   147	        {
   148	          return -EIO;
   149	        }
   150	
   151	      off += (size_t)n;
   152	    }
   153	
   154	  tcdrain(fd);
   155	  return 0;
   156	}
