   158	static void bt_ext_dispatch_frame(struct bt_ext_handle *handle, uint8_t type,
   159	                                  uint8_t subtype, const uint8_t *data,
   160	                                  uint16_t len,
   161	                                  struct bt_ext_waiter *waiter)
   162	{
   163	  struct bt_ext_event event;
   164	
   165	  memset(&event, 0, sizeof(event));
   166	  event.type = BT_EXT_EVENT_RAW_FRAME;
   167	  event.raw_type = type;
   168	  event.raw_subtype = subtype;
   169	  event.data_len = len;
   170	  event.data = data;
   171	
   172	  if (len >= 1)
   173	    {
   174	      event.value = data[0];
   175	    }
   176	
   177	  if (len >= 4)
   178	    {
   179	      event.u32_value = bt_ext_get_le32(data);
   180	    }
   181	
   182	  if (type == VELA_DATA_LOG)
   183	    {
   184	      event.type = BT_EXT_EVENT_LOG;
   185	      event.log_level = (enum bt_ext_log_level)subtype;
   186	    }
   187	  else if (type == VELA_DATA_BLUETOOTH_MUSIC)
   188	    {
   189	      event.type = BT_EXT_EVENT_MUSIC_INFO;
   190	      event.music_attr = (enum bt_ext_music_attr)subtype;
   191	    }
   192	  else if (type == VELA_DATA_STATUS && len >= 1)
   193	    {
   194	      event.status_type = (enum bt_ext_status_type)subtype;
   195	
   196	      if (subtype == BT_EXT_STATUS_BLUETOOTH)
   197	        {
   198	          event.type = BT_EXT_EVENT_CONNECTION_STATE;
   199	        }
   200	      else if (subtype == BT_EXT_STATUS_PLAY_STATE)
   201	        {
   202	          event.type = BT_EXT_EVENT_PLAY_STATE;
   203	        }
   204	      else if (subtype == BT_EXT_STATUS_AUDIO_SOURCE)
   205	        {
   206	          event.type = BT_EXT_EVENT_AUDIO_SOURCE;
   207	        }
   208	    }
   209	  else if (type == VELA_CMD_BLUETOOTH && len >= 1)
   210	    {
   211	      event.type = BT_EXT_EVENT_COMMAND_RESPONSE;
   212	      event.cmd = (enum bt_ext_cmd)subtype;
   213	    }
   214	
   215	  if (waiter != NULL && waiter->active && type == waiter->type &&
   216	      subtype == waiter->subtype && len >= 1)
   217	    {
   218	      waiter->value = data[0];
   219	      waiter->matched = true;
   220	    }
   221	
   222	  if (handle->event_cb != NULL)
   223	    {
   224	      handle->event_cb(&event, handle->event_arg);
   225	    }
   226	}
