   228	static int bt_ext_parse_buffer(struct bt_ext_handle *handle,
   229	                               struct bt_ext_waiter *waiter)
   230	{
   231	  while (handle->used >= BT_EXT_FRAME_HEADER_SIZE)
   232	    {
   233	      uint16_t len = ((uint16_t)handle->rx[3] << 8) | handle->rx[2];
   234	      size_t total = BT_EXT_FRAME_HEADER_SIZE + len;
   235	
   236	      if (total > sizeof(handle->rx))
   237	        {
   238	          memmove(handle->rx, handle->rx + 1, handle->used - 1);
   239	          handle->used--;
   240	          continue;
   241	        }
   242	
   243	      if (handle->used < total)
   244	        {
   245	          break;
   246	        }
   247	
   248	      bt_ext_dispatch_frame(handle, handle->rx[0], handle->rx[1],
   249	                            handle->rx + BT_EXT_FRAME_HEADER_SIZE,
   250	                            len, waiter);
   251	
   252	      if (handle->used > total)
   253	        {
   254	          memmove(handle->rx, handle->rx + total, handle->used - total);
   255	        }
   256	
   257	      handle->used -= total;
   258	
   259	      if (waiter != NULL && waiter->matched)
   260	        {
   261	          break;
   262	        }
   263	    }
   264	
   265	  if (handle->used == sizeof(handle->rx))
   266	    {
   267	      handle->used = 0;
   268	    }
   269	
   270	  return 0;
   271	}
