   273	static int bt_ext_poll_read(struct bt_ext_handle *handle, int wait_ms)
   274	{
   275	  struct pollfd pfd;
   276	  ssize_t n;
   277	  int ret;
   278	
   279	  pfd.fd = handle->fd;
   280	  pfd.events = POLLIN;
   281	  pfd.revents = 0;
   282	
   283	  ret = poll(&pfd, 1, wait_ms);
   284	  if (ret < 0)
   285	    {
   286	      if (errno == EINTR)
   287	        {
   288	          return 0;
   289	        }
   290	
   291	      return -errno;
   292	    }
   293	
   294	  if (ret == 0)
   295	    {
   296	      return 0;
   297	    }
   298	
   299	  if ((pfd.revents & (POLLERR | POLLHUP | POLLNVAL)) != 0)
   300	    {
   301	      return -EIO;
   302	    }
   303	
   304	  if ((pfd.revents & POLLIN) == 0)
   305	    {
   306	      return 0;
   307	    }
   308	
   309	  if (handle->used == sizeof(handle->rx))
   310	    {
   311	      handle->used = 0;
   312	    }
   313	
   314	  n = read(handle->fd, handle->rx + handle->used,
   315	           sizeof(handle->rx) - handle->used);
   316	  if (n < 0)
   317	    {
   318	      if (errno == EINTR || errno == EAGAIN)
   319	        {
   320	          return 0;
   321	        }
   322	
   323	      return -errno;
   324	    }
   325	
   326	  if (n == 0)
   327	    {
   328	      return -EIO;
   329	    }
   330	
   331	  handle->used += (size_t)n;
   332	  return 0;
   333	}
