   335	static int bt_ext_read_frames(struct bt_ext_handle *handle,
   336	                              uint32_t timeout_ms,
   337	                              struct bt_ext_waiter *waiter)
   338	{
   339	  uint32_t elapsed = 0;
   340	  int ret;
   341	
   342	  ret = bt_ext_parse_buffer(handle, waiter);
   343	  if (ret < 0 || (waiter != NULL && waiter->matched))
   344	    {
   345	      return ret;
   346	    }
   347	
   348	  if (timeout_ms == BT_EXT_TIMEOUT_NONE)
   349	    {
   350	      ret = bt_ext_poll_read(handle, 0);
   351	      if (ret < 0)
   352	        {
   353	          return ret;
   354	        }
   355	
   356	      return bt_ext_parse_buffer(handle, waiter);
   357	    }
   358	
   359	  while (timeout_ms == BT_EXT_TIMEOUT_FOREVER || elapsed < timeout_ms)
   360	    {
   361	      int wait_ms = 100;
   362	
   363	      if (timeout_ms != BT_EXT_TIMEOUT_FOREVER &&
   364	          timeout_ms - elapsed < (uint32_t)wait_ms)
   365	        {
   366	          wait_ms = (int)(timeout_ms - elapsed);
   367	        }
   368	
   369	      ret = bt_ext_poll_read(handle, wait_ms);
   370	      if (ret < 0)
   371	        {
   372	          return ret;
   373	        }
   374	
   375	      ret = bt_ext_parse_buffer(handle, waiter);
   376	      if (ret < 0 || (waiter != NULL && waiter->matched))
   377	        {
   378	          return ret;
   379	        }
   380	
   381	      if (timeout_ms != BT_EXT_TIMEOUT_FOREVER)
   382	        {
   383	          elapsed += (uint32_t)wait_ms;
   384	        }
   385	    }
   386	
   387	  return 0;
   388	}
