   105	static unsigned char *wrap_pcm_as_wav(const unsigned char *pcm,
   106	                                      size_t pcm_len,
   107	                                      size_t *wav_len)
   108	{
   109	  const uint32_t sample_rate = VELACLAW_VOICE_SAMPLE_RATE;
   110	  const uint16_t channels = VELACLAW_VOICE_CHANNELS;
   111	  const uint16_t bits = VELACLAW_VOICE_BITS;
   112	  const uint16_t block_align = channels * bits / 8;
   113	  const uint32_t byte_rate = sample_rate * block_align;
   114	  unsigned char *wav;
   115	
   116	  if (pcm == NULL || pcm_len == 0 || wav_len == NULL ||
   117	      pcm_len > UINT32_MAX - 44) {
   118	    return NULL;
   119	  }
   120	
   121	  wav = malloc(pcm_len + 44);
   122	  if (wav == NULL) {
   123	    return NULL;
   124	  }
   125	
   126	  memcpy(wav, "RIFF", 4);
   127	  put_le32(wav + 4, (uint32_t)(pcm_len + 36));
   128	  memcpy(wav + 8, "WAVEfmt ", 8);
   129	  put_le32(wav + 16, 16);
   130	  put_le16(wav + 20, 1);
   131	  put_le16(wav + 22, channels);
   132	  put_le32(wav + 24, sample_rate);
   133	  put_le32(wav + 28, byte_rate);
   134	  put_le16(wav + 32, block_align);
   135	  put_le16(wav + 34, bits);
   136	  memcpy(wav + 36, "data", 4);
   137	  put_le32(wav + 40, (uint32_t)pcm_len);
   138	  memcpy(wav + 44, pcm, pcm_len);
   139	  *wav_len = pcm_len + 44;
   140	  return wav;
   141	}
