   223	static int copy_json_content(cJSON *content, char *out, size_t out_cap)
   224	{
   225	  size_t used = 0;
   226	
   227	  if (content == NULL || out == NULL || out_cap == 0) {
   228	    return -EINVAL;
   229	  }
   230	
   231	  out[0] = '\0';
   232	
   233	  if (cJSON_IsString(content)) {
   234	    snprintf(out, out_cap, "%s", content->valuestring);
   235	    return out[0] ? 0 : -ENODATA;
   236	  }
   237	
   238	  if (cJSON_IsArray(content)) {
   239	    int count = cJSON_GetArraySize(content);
   240	
   241	    for (int i = 0; i < count && used + 1 < out_cap; i++) {
   242	      cJSON *item = cJSON_GetArrayItem(content, i);
   243	      const char *s = json_string_at(item, "text", NULL, NULL, NULL);
   244	
   245	      if (s == NULL) {
   246	        s = json_string_at(item, "input_text", NULL, NULL, NULL);
   247	      }
   248	      if (s == NULL) {
   249	        s = json_string_at(item, "content", NULL, NULL, NULL);
   250	      }
   251	      if (s != NULL) {
   252	        int n = snprintf(out + used, out_cap - used, "%s", s);
   253	
   254	        if (n < 0) {
   255	          return -EIO;
   256	        }
   257	        if ((size_t)n >= out_cap - used) {
   258	          used = out_cap - 1;
   259	          break;
   260	        }
   261	        used += (size_t)n;
   262	      }
   263	    }
   264	
   265	    return out[0] ? 0 : -ENODATA;
   266	  }
   267	
   268	  return -ENODATA;
   269	}
