   121	            ts.tv_sec += (time_t)(timeout_ms / 1000);
   122	            ts.tv_nsec += (long)((timeout_ms % 1000) * 1000000L);
   123	            if (ts.tv_nsec >= 1000000000L) {
   124	                ts.tv_sec++;
