   202	/* ── Persistent connection pool (keep-alive) ─────────────────── */
   203	/* Keeps one live TLS connection per host:port so repeated calls to
   204	 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */
   205	
   206	#define CONN_POOL_SIZE 3
   207	
   208	typedef struct {
   209	    tls_ctx_t ctx;
   210	    char      host[128];
   211	    char      port[8];
   212	    bool      in_use;   /* locked by a request */
   213	    bool      valid;    /* connection is alive */
   214	} conn_slot_t;
   215	
   216	static conn_slot_t   s_pool[CONN_POOL_SIZE];
   217	static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;
   218	
   219	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
   220	static conn_slot_t *pool_acquire(const char *host, const char *port)
   221	{
   222	    pthread_mutex_lock(&s_pool_lock);
   223	
   224	    /* 1. Find an existing valid slot for this host:port */
   225	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
   226	        conn_slot_t *s = &s_pool[i];
   227	        if (s->valid && !s->in_use &&
   228	            strcmp(s->host, host) == 0 &&
   229	            strcmp(s->port, port) == 0) {
   230	            s->in_use = true;
   231	            pthread_mutex_unlock(&s_pool_lock);
   232	            return s;
   233	        }
   234	    }
   235	
   236	    /* 2. Find an empty slot */
   237	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
   238	        if (!s_pool[i].valid && !s_pool[i].in_use) {
   239	            s_pool[i].in_use = true;
   240	            pthread_mutex_unlock(&s_pool_lock);
   241	            return &s_pool[i];
   242	        }
   243	    }
   244	
   245	    /* 3. Evict the first non-in-use slot */
   246	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
   247	        if (!s_pool[i].in_use) {
   248	            tls_ctx_free(&s_pool[i].ctx);
   249	            s_pool[i].valid  = false;
   250	            s_pool[i].in_use = true;
   251	            pthread_mutex_unlock(&s_pool_lock);
   252	            return &s_pool[i];
   253	        }
   254	    }
   255	
   256	    pthread_mutex_unlock(&s_pool_lock);
   257	    return NULL;  /* all slots busy — caller falls back to ephemeral */
   258	}
